package com.masalewala.api.controller;
import com.masalewala.api.dto.Requests.*;import com.masalewala.api.model.Models.*;import com.masalewala.api.repository.Repositories.*;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api") public class CommerceController{private final Users users;private final Addresses addresses;private final Products products;private final Orders orders;private final Payments payments;private final Wishlists wishlists;@Value("${app.upi-id}") String upiId;CommerceController(Users u,Addresses a,Products p,Orders o,Payments pay,Wishlists w){users=u;addresses=a;products=p;orders=o;payments=pay;wishlists=w;}@PostMapping("/addresses") Address address(Authentication auth,@Valid @RequestBody AddressRequest r){var a=new Address();a.user=user(auth);a.line1=r.line1();a.city=r.city();a.state=r.state();a.pinCode=r.pinCode();a.phone=r.phone();a.saved=true;return addresses.save(a);}@GetMapping("/orders") Object orders(Authentication auth){return orders.findByUserEmail(auth.getName());}@PostMapping("/orders") Order order(Authentication auth,@RequestBody OrderRequest r){var o=new Order();o.user=user(auth);o.address=addresses.findById(r.addressId()).orElseThrow();o.expectedDelivery=LocalDate.now().plusDays(5);o.trackingNumber="MW"+System.currentTimeMillis();BigDecimal sub=BigDecimal.ZERO;for(var item:r.items()){var p=products.findById(item.productId()).orElseThrow();var oi=new OrderItem();oi.order=o;oi.product=p;oi.weight=item.weight();oi.quantity=item.quantity();oi.price=p.price;sub=sub.add(p.price.multiply(BigDecimal.valueOf(item.quantity())));o.items.add(oi);}o.subtotal=sub;o.gst=sub.multiply(new BigDecimal("0.05")).setScale(0,RoundingMode.HALF_UP);o.shipping=sub.compareTo(new BigDecimal("999"))>0?BigDecimal.ZERO:new BigDecimal("79");o.grandTotal=o.subtotal.add(o.gst).add(o.shipping);return orders.save(o);}@GetMapping("/orders/track/{tracking}") Object track(@PathVariable String tracking){return orders.findByTrackingNumber(tracking).orElseThrow();}@PostMapping("/payments") Payment payment(@RequestBody PaymentRequest r){var p=payments.findByOrderId(r.orderId()).orElse(new Payment());p.order=orders.findById(r.orderId()).orElseThrow();p.method=r.method();p.upiId=upiId;p.screenshotUrl=r.screenshotUrl();p.razorpayPaymentId=r.razorpayPaymentId();p.status=r.screenshotUrl()!=null?PaymentStatus.UPLOADED:PaymentStatus.PENDING;return payments.save(p);}@GetMapping("/wishlist") Object wishlist(){return wishlists.findAll();}private User user(Authentication auth){return users.findByEmail(auth.getName()).orElseThrow();}}
